import{_ as e,o as r,c as t,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"迭代与生命周期治理","description":"用真实结果管理 Agent 的迭代、能力版本、用户迁移、弃用与退役，形成可追踪的生命周期决策。","frontmatter":{"title":"迭代与生命周期治理","description":"用真实结果管理 Agent 的迭代、能力版本、用户迁移、弃用与退役，形成可追踪的生命周期决策。","verified_at":"2026-08-06","source":["https://semver.org/","https://sre.google/sre-book/canarying-releases/","https://sre.google/sre-book/release-engineering/","https://www.nist.gov/itl/ai-risk-management-framework"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/delivery-evolution/iteration-migration-retirement.md","filePath":"py-agent/architecture/delivery-evolution/iteration-migration-retirement.md","lastUpdated":1786083160000}'),l={name:"py-agent/architecture/delivery-evolution/iteration-migration-retirement.md"};function n(o,a,h,s,d,p){return r(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="迭代与生命周期治理" tabindex="-1">迭代与生命周期治理 <a class="header-anchor" href="#迭代与生命周期治理" aria-label="Permalink to &quot;迭代与生命周期治理&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 上线后会持续变化：用户任务和数据分布变化，模型供应商更新，Prompt、工具、Workflow 和索引不断演进。生命周期治理的目标不是让系统永远增加能力，而是让团队能够基于证据改进、控制变化范围、帮助用户完成迁移，并在价值不足或风险过高时完整退役。</p><p>本章负责产品与系统层的生命周期决策。代码、Schema、模型和索引怎样兼容发布与回滚，见<a href="/py-agent/quality/deployment-reliability/version-migration-release-rollback">版本迁移、发布与回滚</a>；运行中 Workflow 与 Checkpoint 的兼容，见<a href="/py-agent/workflow/workflow-quality/version-migration-release-recovery">版本迁移与发布恢复</a>。</p><h2 id="_1-生命周期状态" tabindex="-1">1. 生命周期状态 <a class="header-anchor" href="#_1-生命周期状态" aria-label="Permalink to &quot;1. 生命周期状态&quot;">​</a></h2><h3 id="_1-1-discovery" tabindex="-1">1.1 Discovery <a class="header-anchor" href="#_1-1-discovery" aria-label="Permalink to &quot;1.1 Discovery&quot;">​</a></h3><p>验证问题、目标用户、数据和风险是否值得建设。输出可证伪假设和退出标准，不急于固定永久架构。</p><h3 id="_1-2-pilot" tabindex="-1">1.2 Pilot <a class="header-anchor" href="#_1-2-pilot" aria-label="Permalink to &quot;1.2 Pilot&quot;">​</a></h3><p>在有限用户、权限和流量内验证真实质量、交互、运营与经济性。Pilot 必须预先定义扩大、延长、回退和终止条件。</p><h3 id="_1-3-general-availability" tabindex="-1">1.3 General Availability <a class="header-anchor" href="#_1-3-general-availability" aria-label="Permalink to &quot;1.3 General Availability&quot;">​</a></h3><p>产品范围、SLO、支持责任和风险控制稳定，变更进入正式评测与发布门禁。GA 是服务承诺，不是打开一个全量开关。</p><h3 id="_1-4-maintenance" tabindex="-1">1.4 Maintenance <a class="header-anchor" href="#_1-4-maintenance" aria-label="Permalink to &quot;1.4 Maintenance&quot;">​</a></h3><p>以可靠性、数据新鲜度、成本和必要兼容更新为主，限制新增范围。Maintenance 不是无人维护，而是改变投入目标。</p><h3 id="_1-5-deprecated" tabindex="-1">1.5 Deprecated <a class="header-anchor" href="#_1-5-deprecated" aria-label="Permalink to &quot;1.5 Deprecated&quot;">​</a></h3><p>能力仍可使用，但不再推荐，已有替代方案、通知计划和停止日期。弃用期间应限制新用户进入，而不是继续扩展功能。</p><h3 id="_1-6-retired" tabindex="-1">1.6 Retired <a class="header-anchor" href="#_1-6-retired" aria-label="Permalink to &quot;1.6 Retired&quot;">​</a></h3><p>入口、任务、权限、数据处理和运营责任已按计划停止。隐藏入口或关闭部署不等于完成退役。</p><h2 id="_2-生命周期证据" tabindex="-1">2. 生命周期证据 <a class="header-anchor" href="#_2-生命周期证据" aria-label="Permalink to &quot;2. 生命周期证据&quot;">​</a></h2><h3 id="_2-1-用户结果" tabindex="-1">2.1 用户结果 <a class="header-anchor" href="#_2-1-用户结果" aria-label="Permalink to &quot;2.1 用户结果&quot;">​</a></h3><p>观察任务成功、处理时间、返工、人工接管、用户纠正和申诉。消息数、点赞和使用时长只能作为辅助信号，不能单独证明业务价值。</p><h3 id="_2-2-质量证据" tabindex="-1">2.2 质量证据 <a class="header-anchor" href="#_2-2-质量证据" aria-label="Permalink to &quot;2.2 质量证据&quot;">​</a></h3><p>使用离线评测、在线抽样、错误分类和关键 Slice 判断系统在哪些任务上变好或变差。模型总分变化不直接说明应修改 Prompt、RAG、工具还是交互。</p><h3 id="_2-3-运行与经济证据" tabindex="-1">2.3 运行与经济证据 <a class="header-anchor" href="#_2-3-运行与经济证据" aria-label="Permalink to &quot;2.3 运行与经济证据&quot;">​</a></h3><p>Trace、错误、延迟、队列、恢复、每成功任务成本和人工成本共同描述系统是否可持续。失败重试可能同时推高成本并降低用户体验。</p><h3 id="_2-4-风险与治理证据" tabindex="-1">2.4 风险与治理证据 <a class="header-anchor" href="#_2-4-风险与治理证据" aria-label="Permalink to &quot;2.4 风险与治理证据&quot;">​</a></h3><p>安全事件、权限拒绝、数据删除、供应商政策和法规变化可能触发立即复查。高风险变化不应排在普通产品优化队列里等待。</p><h3 id="_2-5-技术健康" tabindex="-1">2.5 技术健康 <a class="header-anchor" href="#_2-5-技术健康" aria-label="Permalink to &quot;2.5 技术健康&quot;">​</a></h3><p>依赖生命周期、模型停服通知、索引重建时间、测试稳定性和运维负担决定系统还能否安全变化。只按用户功能排期会逐渐形成无法发布的系统。</p><h2 id="_3-从问题到迭代假设" tabindex="-1">3. 从问题到迭代假设 <a class="header-anchor" href="#_3-从问题到迭代假设" aria-label="Permalink to &quot;3. 从问题到迭代假设&quot;">​</a></h2><h3 id="_3-1-错误分类" tabindex="-1">3.1 错误分类 <a class="header-anchor" href="#_3-1-错误分类" aria-label="Permalink to &quot;3.1 错误分类&quot;">​</a></h3><p>按输入理解、上下文与检索、决策、工具、状态、生成、系统和交互分类，并附 Task、Trace 和版本证据。主因与伴随因素分开，避免把所有失败归为“模型不够好”。</p><h3 id="_3-2-优先级" tabindex="-1">3.2 优先级 <a class="header-anchor" href="#_3-2-优先级" aria-label="Permalink to &quot;3.2 优先级&quot;">​</a></h3><p>综合用户损失、频率、不可逆性、影响范围、可检测性和修复信心。低频跨租户访问必须优先于高频文风问题，不能只按数量排序。</p><h3 id="_3-3-改进层" tabindex="-1">3.3 改进层 <a class="header-anchor" href="#_3-3-改进层" aria-label="Permalink to &quot;3.3 改进层&quot;">​</a></h3><table tabindex="0"><thead><tr><th>错误模式</th><th>优先检查</th></tr></thead><tbody><tr><td>事实未召回</td><td>数据、切分、检索、权限</td></tr><tr><td>证据存在但回答错误</td><td>Context、Prompt、模型</td></tr><tr><td>工具参数错误</td><td>Schema、描述、校验、纠错</td></tr><tr><td>重复副作用</td><td>状态、幂等、恢复</td></tr><tr><td>用户误解动作</td><td>产品交互与确认</td></tr><tr><td>尾延迟或超支</td><td>路由、预算、并发、缓存</td></tr></tbody></table><p>不要用增加一条 Prompt 规则修复属于数据、状态或权限边界的问题。</p><h3 id="_3-4-可证伪假设" tabindex="-1">3.4 可证伪假设 <a class="header-anchor" href="#_3-4-可证伪假设" aria-label="Permalink to &quot;3.4 可证伪假设&quot;">​</a></h3><p>每项迭代写明目标 Slice、错误模式、拟议变化、主要指标、护栏、数据集、观察窗口和失败处置。例如：“调整检索重排后，长政策问答成功率提高至少 4 个百分点，同时引用准确率不得下降超过 1 个百分点。”</p><h2 id="_4-变更治理" tabindex="-1">4. 变更治理 <a class="header-anchor" href="#_4-变更治理" aria-label="Permalink to &quot;4. 变更治理&quot;">​</a></h2><h3 id="_4-1-变更分类" tabindex="-1">4.1 变更分类 <a class="header-anchor" href="#_4-1-变更分类" aria-label="Permalink to &quot;4.1 变更分类&quot;">​</a></h3><p>行为变更包括 Prompt、模型和工具描述；契约变更包括 API、事件和 State Schema；数据变更包括语料、权限和索引；运行变更包括框架、推理引擎和资源；风险变更包括新工具、新地域或更高自动化等级。</p><p>分类的目的不是贴标签，而是确定谁批准、哪些数据集需要重跑、哪些用户受影响以及能否独立回退。</p><h3 id="_4-2-影响范围" tabindex="-1">4.2 影响范围 <a class="header-anchor" href="#_4-2-影响范围" aria-label="Permalink to &quot;4.2 影响范围&quot;">​</a></h3><p>一次变更可能只影响一个任务 Slice，也可能改变全部租户、长任务状态或外部系统契约。变更记录要列出直接消费者、存量任务、数据副本、人工流程和支持文档。</p><h3 id="_4-3-所有权" tabindex="-1">4.3 所有权 <a class="header-anchor" href="#_4-3-所有权" aria-label="Permalink to &quot;4.3 所有权&quot;">​</a></h3><p>产品负责人拥有用户结果，领域负责人拥有业务口径，工程负责人拥有实现，质量和安全负责人拥有门禁，运营负责人拥有迁移与支持。不能由修改 Prompt 的同一个人自行定义、执行并批准全部证据。</p><h3 id="_4-4-完整版本" tabindex="-1">4.4 完整版本 <a class="header-anchor" href="#_4-4-完整版本" aria-label="Permalink to &quot;4.4 完整版本&quot;">​</a></h3><p>一次运行应能够追溯应用、配置、Prompt、工具目录、Workflow、模型、索引、策略和评测版本。Release Manifest 的实现属于发布工程；生命周期治理使用它判断“哪个能力版本产生了什么结果”。</p><h2 id="_5-迭代闭环" tabindex="-1">5. 迭代闭环 <a class="header-anchor" href="#_5-迭代闭环" aria-label="Permalink to &quot;5. 迭代闭环&quot;">​</a></h2><h3 id="_5-1-建立基线" tabindex="-1">5.1 建立基线 <a class="header-anchor" href="#_5-1-建立基线" aria-label="Permalink to &quot;5.1 建立基线&quot;">​</a></h3><p>在同一任务分布和关键 Slice 上保存当前批准版本的数据。没有基线，候选的演示成功无法说明产生了净收益。</p><h3 id="_5-2-控制变量" tabindex="-1">5.2 控制变量 <a class="header-anchor" href="#_5-2-控制变量" aria-label="Permalink to &quot;5.2 控制变量&quot;">​</a></h3><p>一次实验尽量只改变可解释的一组因素。若同时更换模型、Prompt、索引和工具，结果提高也无法知道哪个变化应保留。</p><h3 id="_5-3-离线与在线证据" tabindex="-1">5.3 离线与在线证据 <a class="header-anchor" href="#_5-3-离线与在线证据" aria-label="Permalink to &quot;5.3 离线与在线证据&quot;">​</a></h3><p>先用版本化数据集验证质量和安全，再以 Shadow、Canary 或受控 Pilot 观察真实分布。实验设计与回归门禁详见<a href="/py-agent/quality/agent-evaluation/evaluation-experiments-regression-gates">评测实验与回归门禁</a>。</p><h3 id="_5-4-判定" tabindex="-1">5.4 判定 <a class="header-anchor" href="#_5-4-判定" aria-label="Permalink to &quot;5.4 判定&quot;">​</a></h3><p>每轮只有四类结论：Advance、Hold、Rollback 或 Stop。没有显著回归不等于应扩大，新增复杂度、延迟或运营成本可能不值得。</p><h3 id="_5-5-回流" tabindex="-1">5.5 回流 <a class="header-anchor" href="#_5-5-回流" aria-label="Permalink to &quot;5.5 回流&quot;">​</a></h3><p>失败样本经脱敏、审核和标注后进入回归集；变更结果更新需求、ADR、Runbook 和用户说明。只修生产样例、不更新长期证据，会让同类问题反复出现。</p><h2 id="_6-能力版本治理" tabindex="-1">6. 能力版本治理 <a class="header-anchor" href="#_6-能力版本治理" aria-label="Permalink to &quot;6. 能力版本治理&quot;">​</a></h2><h3 id="_6-1-版本单位" tabindex="-1">6.1 版本单位 <a class="header-anchor" href="#_6-1-版本单位" aria-label="Permalink to &quot;6.1 版本单位&quot;">​</a></h3><p>用户看到的是“能力”，而不是内部某个 Prompt 文件。一个能力版本可以绑定多个技术版本，并拥有明确范围、自动化等级、数据条件和支持期限。</p><h3 id="_6-2-稳定与实验能力" tabindex="-1">6.2 稳定与实验能力 <a class="header-anchor" href="#_6-2-稳定与实验能力" aria-label="Permalink to &quot;6.2 稳定与实验能力&quot;">​</a></h3><p>实验能力限制用户、数据、权限和时间，并明确结果不进入哪些正式流程。稳定能力必须满足正式 SLO、支持和变更门禁，不能长期借用“Beta”回避责任。</p><h3 id="_6-3-存量任务" tabindex="-1">6.3 存量任务 <a class="header-anchor" href="#_6-3-存量任务" aria-label="Permalink to &quot;6.3 存量任务&quot;">​</a></h3><p>长任务和多轮会话是否固定到启动时的能力版本，要在产品契约中说明。技术上怎样读取旧 State 由工作流迁移文章处理；这里关心用户不会在任务中途无提示地遇到行为变化。</p><h3 id="_6-4-能力目录" tabindex="-1">6.4 能力目录 <a class="header-anchor" href="#_6-4-能力目录" aria-label="Permalink to &quot;6.4 能力目录&quot;">​</a></h3><p>维护当前、实验、弃用和退役能力的目录，记录 Owner、适用用户、依赖、关键指标、替代项和复查日期。目录让产品承诺与技术发布保持可追踪关系。</p><h2 id="_7-用户与租户迁移" tabindex="-1">7. 用户与租户迁移 <a class="header-anchor" href="#_7-用户与租户迁移" aria-label="Permalink to &quot;7. 用户与租户迁移&quot;">​</a></h2><h3 id="_7-1-迁移对象" tabindex="-1">7.1 迁移对象 <a class="header-anchor" href="#_7-1-迁移对象" aria-label="Permalink to &quot;7.1 迁移对象&quot;">​</a></h3><p>迁移的不只是数据，还包括任务入口、默认行为、确认步骤、记忆策略、人工队列和用户形成的工作习惯。技术切流成功不代表用户已经完成迁移。</p><h3 id="_7-2-资格与分组" tabindex="-1">7.2 资格与分组 <a class="header-anchor" href="#_7-2-资格与分组" aria-label="Permalink to &quot;7.2 资格与分组&quot;">​</a></h3><p>按租户配置、数据地域、任务类型、历史状态和支持能力判断谁可以迁移。不能只按随机流量把不兼容用户送入新版本。</p><h3 id="_7-3-告知与选择" tabindex="-1">7.3 告知与选择 <a class="header-anchor" href="#_7-3-告知与选择" aria-label="Permalink to &quot;7.3 告知与选择&quot;">​</a></h3><p>说明变化、收益、限制、时间线、数据影响和回退渠道。高影响用户可能需要明确同意；普通低风险改进也应在行为明显变化时提供可理解说明。</p><h3 id="_7-4-双轨期" tabindex="-1">7.4 双轨期 <a class="header-anchor" href="#_7-4-双轨期" aria-label="Permalink to &quot;7.4 双轨期&quot;">​</a></h3><p>旧能力和新能力可以短期并存，让用户比较或回退。双轨会增加培训、数据同步、客服和修复成本，因此开始时就要定义结束条件。</p><h3 id="_7-5-迁移完成" tabindex="-1">7.5 迁移完成 <a class="header-anchor" href="#_7-5-迁移完成" aria-label="Permalink to &quot;7.5 迁移完成&quot;">​</a></h3><p>同时检查技术覆盖、关键任务成功、用户采用、支持工单、旧任务剩余和回退率。只有流量比例达到 100% 不能证明迁移完成。</p><h2 id="_8-弃用决策" tabindex="-1">8. 弃用决策 <a class="header-anchor" href="#_8-弃用决策" aria-label="Permalink to &quot;8. 弃用决策&quot;">​</a></h2><h3 id="_8-1-触发条件" tabindex="-1">8.1 触发条件 <a class="header-anchor" href="#_8-1-触发条件" aria-label="Permalink to &quot;8.1 触发条件&quot;">​</a></h3><ul><li>用户价值或采用长期低于最低标准；</li><li>质量、安全或合规无法经济满足；</li><li>模型或依赖停止支持且无合理替代；</li><li>新能力已替代旧能力，双轨成本持续过高；</li><li>数据源、业务流程或组织责任已经消失；</li><li>每成功任务成本长期高于可接受价值。</li></ul><h3 id="_8-2-候选处置" tabindex="-1">8.2 候选处置 <a class="header-anchor" href="#_8-2-候选处置" aria-label="Permalink to &quot;8.2 候选处置&quot;">​</a></h3><p>在完整弃用前还可以缩小范围、降为只读、转人工、合并到其他能力或进入 Maintenance。决策应比较继续、收缩、替代和退役的成本与风险。</p><h3 id="_8-3-决策权限" tabindex="-1">8.3 决策权限 <a class="header-anchor" href="#_8-3-决策权限" aria-label="Permalink to &quot;8.3 决策权限&quot;">​</a></h3><p>弃用是产品、风险、数据和运营共同决策，不应只因为工程团队想重写系统。高影响能力需要明确批准人和申诉通道。</p><h2 id="_9-弃用期" tabindex="-1">9. 弃用期 <a class="header-anchor" href="#_9-弃用期" aria-label="Permalink to &quot;9. 弃用期&quot;">​</a></h2><h3 id="_9-1-通知" tabindex="-1">9.1 通知 <a class="header-anchor" href="#_9-1-通知" aria-label="Permalink to &quot;9.1 通知&quot;">​</a></h3><p>说明受影响用户、能力、时间线、替代方案、数据处理、支持和申诉。高影响用户需要直接确认，不能只发布一条无人阅读的公告。</p><h3 id="_9-2-冻结" tabindex="-1">9.2 冻结 <a class="header-anchor" href="#_9-2-冻结" aria-label="Permalink to &quot;9.2 冻结&quot;">​</a></h3><p>停止新增租户和非必要能力，只接受安全、兼容和迁移修复。继续扩展旧能力会让截止日期不断后移。</p><h3 id="_9-3-替代验证" tabindex="-1">9.3 替代验证 <a class="header-anchor" href="#_9-3-替代验证" aria-label="Permalink to &quot;9.3 替代验证&quot;">​</a></h3><p>使用真实关键旅程验证替代系统的功能、权限、数据和可访问性。记录无法迁移的任务和人工处置，不能用平均采用率掩盖高风险用户。</p><h3 id="_9-4-只读与截止" tabindex="-1">9.4 只读与截止 <a class="header-anchor" href="#_9-4-只读与截止" aria-label="Permalink to &quot;9.4 只读与截止&quot;">​</a></h3><p>根据风险先停止新写入，再进入查询或导出，最后关闭。每个阶段有开始条件、完成证据、支持责任和最终截止时间。</p><h2 id="_10-退役执行" tabindex="-1">10. 退役执行 <a class="header-anchor" href="#_10-退役执行" aria-label="Permalink to &quot;10. 退役执行&quot;">​</a></h2><h3 id="_10-1-流量与任务" tabindex="-1">10.1 流量与任务 <a class="header-anchor" href="#_10-1-流量与任务" aria-label="Permalink to &quot;10.1 流量与任务&quot;">​</a></h3><p>关闭新入口、队列生产者、定时任务和 Webhook；等待、迁移、取消或补偿在途任务。每个任务必须进入可解释终态并通知相关用户。</p><h3 id="_10-2-数据" tabindex="-1">10.2 数据 <a class="header-anchor" href="#_10-2-数据" aria-label="Permalink to &quot;10.2 数据&quot;">​</a></h3><p>按保留政策归档、迁移或删除业务数据、Checkpoint、记忆、索引、缓存、评测副本、日志和备份。保留法律或审计数据时限制访问和用途。</p><h3 id="_10-3-身份与信任" tabindex="-1">10.3 身份与信任 <a class="header-anchor" href="#_10-3-身份与信任" aria-label="Permalink to &quot;10.3 身份与信任&quot;">​</a></h3><p>撤销用户授权、服务账户、OAuth Client、API Key、证书、Webhook Secret 和跨系统信任。只停止应用进程会留下可利用入口。</p><h3 id="_10-4-基础设施与供应商" tabindex="-1">10.4 基础设施与供应商 <a class="header-anchor" href="#_10-4-基础设施与供应商" aria-label="Permalink to &quot;10.4 基础设施与供应商&quot;">​</a></h3><p>释放模型端点、GPU、数据库、队列、对象存储、域名和订阅，同时确认共享资源不会被误删。账单、配额和供应商数据副本也要进入核对范围。</p><h3 id="_10-5-运营责任" tabindex="-1">10.5 运营责任 <a class="header-anchor" href="#_10-5-运营责任" aria-label="Permalink to &quot;10.5 运营责任&quot;">​</a></h3><p>更新服务目录、Runbook、告警、值班、支持和所有权，关闭无意义的 Page，保留必要审计与退役负责人。</p><h2 id="_11-退出验收" tabindex="-1">11. 退出验收 <a class="header-anchor" href="#_11-退出验收" aria-label="Permalink to &quot;11. 退出验收&quot;">​</a></h2><p>退役只有在以下证据成立时完成：</p><ul><li>新请求稳定返回正式停用或迁移信息，而非随机连接错误；</li><li>在途任务均有终态和用户通知；</li><li>替代系统关键旅程、数据计数和权限一致；</li><li>已撤销身份和凭据不能再访问；</li><li>已删除数据不会从索引、缓存和新会话返回；</li><li>供应商和基础设施账单归零或符合保留计划；</li><li>审计、决策和用户申诉记录仍可按政策查询。</li></ul><p>删除链路的具体机制可参考<a href="/py-agent/quality/security-governance/privacy-compliance-responsible-ai">隐私、合规与负责任 AI</a>。</p><h2 id="_12-填写后的生命周期记录" tabindex="-1">12. 填写后的生命周期记录 <a class="header-anchor" href="#_12-填写后的生命周期记录" aria-label="Permalink to &quot;12. 填写后的生命周期记录&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能力：support-agent / policy-answer v2</span></span>
<span class="line"><span>当前阶段：GA -&gt; Deprecated</span></span>
<span class="line"><span>决定日期：2026-08-06</span></span>
<span class="line"><span>依据：v3 关键任务成功率 +6.2pp，每成功任务成本 -18%；</span></span>
<span class="line"><span>      v2 依赖的模型将在 90 天后停止服务</span></span>
<span class="line"><span>受影响：42 个租户，318 个未完成长会话，无写工具</span></span>
<span class="line"><span>替代：v3；长会话可继续 v2 至完成，新会话进入 v3</span></span>
<span class="line"><span>通知：管理员邮件 + 产品内提示；高影响租户由客户成功确认</span></span>
<span class="line"><span>双轨截止：2026-09-15</span></span>
<span class="line"><span>完成标准：未完成 v2 会话 = 0；关键旅程通过；回退率 &lt; 1%</span></span>
<span class="line"><span>退役动作：撤销模型凭据，删除路由，按政策清理 Checkpoint</span></span>
<span class="line"><span>责任：产品 Owner / 平台 Owner / 数据 Owner / 支持 Owner</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>示例展示的是完整治理记录，不是其他系统应直接采用的日期或阈值。</p><h2 id="_13-常见误区" tabindex="-1">13. 常见误区 <a class="header-anchor" href="#_13-常见误区" aria-label="Permalink to &quot;13. 常见误区&quot;">​</a></h2><ol><li><strong>每个问题都改 Prompt</strong>：根因可能在数据、工具、状态或交互。</li><li><strong>Beta 可以无限持续</strong>：用户已经依赖，组织却没有正式责任。</li><li><strong>技术切流等于用户迁移</strong>：工作习惯、权限和支持可能仍未改变。</li><li><strong>隐藏入口就是退役</strong>：任务、数据、凭据和费用仍然存在。</li><li><strong>退役成功只看记录数</strong>：语义、权限和关键旅程可能错误。</li></ol><h2 id="_14-治理检查表" tabindex="-1">14. 治理检查表 <a class="header-anchor" href="#_14-治理检查表" aria-label="Permalink to &quot;14. 治理检查表&quot;">​</a></h2><ul><li>生命周期状态是否有进入、退出条件和明确 Owner；</li><li>迭代是否来自可追踪错误、用户结果和运行证据；</li><li>每项变化是否有目标 Slice、主要指标、护栏和失败处置；</li><li>能力版本是否绑定范围、自动化等级、技术版本和支持期限；</li><li>用户迁移是否覆盖资格、通知、双轨、支持和完成证据；</li><li>弃用是否比较继续、收缩、替代和退役，而非只看工程偏好；</li><li>退役是否清理任务、数据、身份、基础设施、供应商和运营责任；</li><li>生命周期结束后是否仍保留必要的审计、决策和复盘证据。</li></ul><p>成熟系统不以能力数量衡量，而以能否基于证据增加、改变、限制和移除能力衡量。生命周期治理让每次变化都有责任、证据和清楚的结束条件。</p>`,118)])])}const b=e(l,[["render",n]]);export{u as __pageData,b as default};
